const updateDatabaseSync = `-- name: UpdateDatabaseSync :one
UPDATE database_syncs SET
    name = $1,
    mode = $2,
    source_db_id = $3,
    source_name = $4,
    target_db_id = $5,
    target_name = $6,
    trigger = $7,
    cron = $8,
    timezone = $9,
    interval_minutes = $10,
    options = $11,
    marks = $12,
    next_run_at = $13,
    paused = $14,
    problem = '',
    updated_by = $15,
    updated_at = now()
WHERE id = $16
RETURNING id, workspace_id, name, mode, source_db_id, source_name, target_db_id, target_name, trigger, cron, timezone, interval_minutes, options, marks, full_at, paused, next_run_at, problem, created_by, updated_by, created_at, updated_at
`

type UpdateDatabaseSyncParams struct {
	Name            string     `json:"name"`
	Mode            string     `json:"mode"`
	SourceDbID      uuid.UUID  `json:"source_db_id"`
	SourceName      string     `json:"source_name"`
	TargetDbID      uuid.UUID  `json:"target_db_id"`
	TargetName      string     `json:"target_name"`
	Trigger         string     `json:"trigger"`
	Cron            string     `json:"cron"`
	Timezone        string     `json:"timezone"`
	IntervalMinutes int32      `json:"interval_minutes"`
	Options         []byte     `json:"options"`
	Marks           []byte     `json:"marks"`
	NextRunAt       *time.Time `json:"next_run_at"`
	Paused          bool       `json:"paused"`
	UpdatedBy       *uuid.UUID `json:"updated_by"`
	ID              uuid.UUID  `json:"id"`
}

func (q *Queries) UpdateDatabaseSync(ctx context.Context, arg UpdateDatabaseSyncParams) (DatabaseSync, error) {
	row := q.db.QueryRow(ctx, updateDatabaseSync,
		arg.Name,
		arg.Mode,
		arg.SourceDbID,
		arg.SourceName,
		arg.TargetDbID,
		arg.TargetName,
		arg.Trigger,
		arg.Cron,
		arg.Timezone,
		arg.IntervalMinutes,
		arg.Options,
		arg.Marks,
		arg.NextRunAt,
		arg.Paused,
		arg.UpdatedBy,
		arg.ID,
	)
	var i DatabaseSync
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.Name,
		&i.Mode,
		&i.SourceDbID,
		&i.SourceName,
		&i.TargetDbID,
		&i.TargetName,
		&i.Trigger,
		&i.Cron,
		&i.Timezone,
		&i.IntervalMinutes,
		&i.Options,
		&i.Marks,
		&i.FullAt,
		&i.Paused,
		&i.NextRunAt,
		&i.Problem,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
